INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_CWC3_SUMMER_CIV','The Seventeenth Summer'),
 ('TXT_KEY_CWC3_SUMMER_SHORT','Seventeenth Summer'),
 ('TXT_KEY_CWC3_SUMMER_ADJECTIVE','Summer'),
 ('TXT_KEY_CWC3_SUMMER_LEADER','Chorus-Mother Ixa'),
 ('TXT_KEY_CWC3_SUMMER_TRAIT','The Great Emergence'),
 ('TXT_KEY_CWC3_SUMMER_TRAIT_HELP','Repeat Dormancy (+1 [ICON_FOOD] Food per city) and Emergence (+2 [ICON_PRODUCTION] Production and +1 [ICON_CULTURE] Culture per city). The first processed owner-turn is Dormancy turn 1. Phase changes occur after that turn''s economic collection, apply immediately to combat, and schedule city yields for the next economic payout. At Standard speed, owner-turns 1-13 are Dormancy, 14-17 Emergence, 18-30 Dormancy, and 31-34 Emergence. Quick: 9/3; Standard: 13/4; Epic: 20/6; Marathon: 39/12 (Dormancy/Emergence).'),
 ('TXT_KEY_CWC3_SUMMER_CIV_PEDIA','We Were Never Gone. Intelligent cicada-like people sleep beneath the roots, preserving their memories in tree rings and amber. Their synchronized return fills the summer canopy with a chorus of discovery and creation. The first processed owner-turn is Dormancy turn 1. Phase changes occur after that turn''s economic collection, apply immediately to combat, and schedule city yields for the next economic payout. At Standard speed, owner-turns 1-13 are Dormancy, 14-17 Emergence, 18-30 Dormancy, and 31-34 Emergence. Quick: 9/3; Standard: 13/4; Epic: 20/6; Marathon: 39/12 (Dormancy/Emergence).'),
 ('TXT_KEY_CWC3_SUMMER_LEADER_PEDIA','Chorus-Mother Ixa is a regal cicada queen with translucent golden wings and tree-ring markings. She rules from an amber-and-root throne beneath the earth, measuring the histories of surface empires in the patient intervals between summers.'),
 ('TXT_KEY_CWC3_SUMMER_STRATEGY','Favor Science and Culture. Grow during Dormancy; time production and military campaigns for Emergence. Build Brood Nurseries and preserve Shellguard veterans. The first processed owner-turn is Dormancy turn 1. Phase changes occur after that turn''s economic collection, apply immediately to combat, and schedule city yields for the next economic payout. At Standard speed, owner-turns 1-13 are Dormancy, 14-17 Emergence, 18-30 Dormancy, and 31-34 Emergence. Quick: 9/3; Standard: 13/4; Epic: 20/6; Marathon: 39/12 (Dormancy/Emergence).'),
 ('TXT_KEY_CWC3_SUMMER_UNIT','Shellguard'),
 ('TXT_KEY_CWC3_SUMMER_UNIT_HELP','Replaces the active Spearman with +1 Sight. All other baseline properties and companion effects are inherited. Shellguards and their upgraded descendants receive +20% Combat Strength attacking and defending during Emergence while owned by a human Seventeenth Summer player. Brood lineage survives multiple upgrades; ordinary Spearmen never gain it. Extra Sight belongs to the Shellguard unit type.'),
 ('TXT_KEY_CWC3_SUMMER_UNIT_PEDIA','Armored in the memory of old shells, these watchful soldiers guard the brood through the quiet years. Their descendants answer the chorus when the summer returns.'),
 ('TXT_KEY_CWC3_SUMMER_NURSERY','Brood Nursery'),
 ('TXT_KEY_CWC3_SUMMER_NURSERY_HELP','Replaces the active Granary and preserves its normal effects. Adds +1 [ICON_PEACE] Faith permanently, plus +1 [ICON_PRODUCTION] Production during Emergence under eligible Summer ownership. With the UA, unique bonuses total +1 Food and +1 Faith in Dormancy, or +3 Production, +1 Culture and +1 Faith in Emergence. Phase yields apply to the next payout.'),
 ('TXT_KEY_CWC3_SUMMER_NURSERY_PEDIA','Under branching roots, the next generation grows in chambers warm with amber light. When the chorus sounds, quiet care becomes a burst of shared labor.'),
 ('TXT_KEY_CWC3_SUMMER_LINEAGE','Brood Lineage'),
 ('TXT_KEY_CWC3_SUMMER_LINEAGE_HELP','Internal permanent Shellguard ancestry marker. Cannot be selected; survives upgrades. No independent yield or combat effect.'),
 ('TXT_KEY_CWC3_SUMMER_AWAKENED','Awakened'),
 ('TXT_KEY_CWC3_SUMMER_AWAKENED_HELP','+20% Combat Strength attacking and defending during Emergence. Requires Shellguard lineage and eligible Summer ownership.'),
 ('TXT_KEY_CWC3_SUMMER_DUMMY','Summer Cycle'),
 ('TXT_KEY_CWC3_SUMMER_DUMMY_HELP','Invisible internal zero/one phase yield controller. Cannot be constructed or purchased.'),
 ('TXT_KEY_CWC3_SUMMER_EMERGENCE_TITLE','The Great Emergence'),
 ('TXT_KEY_CWC3_SUMMER_EMERGENCE_NOTICE','We Were Never Gone. Emergence begins: +2 Production and +1 Culture per city, +1 Production per Brood Nursery, and +20% Combat Strength for brood veterans. City bonuses apply to the next economic payout.'),
 ('TXT_KEY_CWC3_SUMMER_DORMANCY_TITLE','Beneath the Roots'),
 ('TXT_KEY_CWC3_SUMMER_DORMANCY_NOTICE','The chorus returns to Dormancy: +1 Food per city; Awakened and Emergence Production/Culture end. City bonuses apply to the next economic payout.'),
 ('TXT_KEY_CWC3_SUMMER_GREETING_1','Another visitor from the surface? How curious. Tell me, little one... how many summers have passed since we last spoke?'),
 ('TXT_KEY_CWC3_SUMMER_WAR_1','We have waited seventeen summers for this moment. You shall not make us wait another.'),
 ('TXT_KEY_CWC3_SUMMER_ATTACKED_1','You have chosen an unfortunate season.'),
 ('TXT_KEY_CWC3_SUMMER_DEFEAT_1','Our voices fade... but beneath the earth... another generation waits.'),
 ('TXT_KEY_CWC3_SUMMER_FALLBACK_1','Beneath the earth, we remember. Let your words join the chorus.'),
 ('TXT_KEY_CWC3_SUMMER_DAWN','Chorus-Mother Ixa, the roots stir beneath your amber throne. Your golden wings remember the light, and your people await the seventeenth summer. Grow through the quiet years, build halls for the brood, and let your emergence fill the world with knowledge and song. We Were Never Gone.'),
 ('TXT_KEY_CWC3_SUMMER_CITY_1','First Emergence'),
 ('TXT_KEY_CWC3_SUMMER_CITY_2','Amber Root'),
 ('TXT_KEY_CWC3_SUMMER_CITY_3','Seventeen Rings'),
